report_graph:
@prefix dc: <http://purl.org/dc/elements/1.1/> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode skos:Concept ;
            sh:resultMessage "owl:Class should specify provenance via dc:source." ;
            sh:resultPath dc:source ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "owl:Class should specify provenance via dc:source." ;
                    sh:minCount 1 ;
                    sh:path dc:source ;
                    sh:severity sh:Warning ] ],
        [ a sh:ValidationResult ;
            sh:focusNode <http://depo-onto.local/xsd#bom/> ;
            sh:resultMessage "owl:Ontology should specify owl:versionInfo." ;
            sh:resultPath owl:versionInfo ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:datatype xsd:string ;
                    sh:message "owl:Ontology should specify owl:versionInfo." ;
                    sh:minCount 1 ;
                    sh:path owl:versionInfo ;
                    sh:severity sh:Warning ] ] .
